public class SafeActionDispatcher
{
    public async Task ExecuteOrderActionAsync(string rawModelOutput, CancellationToken ct)
    {
        // 1. Never execute raw scripts - deserialize into strict record schema
        OrderActionCommand? command;
        try
        {
            command = JsonSerializer.Deserialize<OrderActionCommand>(rawModelOutput);
        }
        catch (JsonException ex)
        {
            throw new SecurityException("Malformed AI output rejected: invalid JSON schema.", ex);
        }

        // 2. Enforce strict parameter range validation
        if (command == null || command.Quantity <= 0 || command.Quantity > 100)
        {
            throw new ArgumentOutOfRangeException(nameof(command.Quantity), "Quantity exceeds safety bounds (1-100).");
        }

        // 3. Execute parameterized database transaction with least privilege
        await _orderService.UpdateQuantityAsync(command.OrderId, command.Quantity, ct);
    }
}

public record OrderActionCommand(string OrderId, int Quantity);
